-- ov3-harness-06-owner-objective.sql
--
-- ============================== PREFLIGHT - NOT AN INSTALL ==============================
-- Byte-identical to the .commit twin except this banner and the terminal statement:
-- ROLLBACK TRANSACTION here, COMMIT TRANSACTION there. Nothing is written.
--
-- WHAT THIS ADDS (owner direction 2026-11-02, revised after the owner's review of census-2 the same day):
--   analysis.read_capability_census_sources - every recorded obligation from rows: each tracker project, each task of the
--     named project, each quoted line of the newest owner-direction row; with the specification and the capability ids.
--   analysis.check_capability_census - the id check: every obligation id answered, 1 to maxAreas valid unique areas (the flight passes 60;
--     the writer aims for 30), every required concern covered; citations the estate does not hold are removed and reported.
--   analysis.check_census_fulfillment - the fulfillment gate: an obligation counts as owned only when an area that claims it
--     was judged, by a separate ask-model pass, to do what it requires. Rejected claims are removed and reported, and the
--     feedback names every defect for OV3 to correct. The id check alone passed one unrelated area claiming everything
--     (review run 15e76f2e; probe de596392).
--   analysis.select_census_result - keeps the first of two correction rounds whose census passed, so a census that passed is
--     never lost to a second judgment.
--   analysis.verify_model_binding - checks each model call's receipt against the estate's declared binding (MODEL_SELECTION of
--     its role, else default, from sidefx:model-providers): BINDING_HONORED or BINDING_VIOLATED before anything is retained.
--   analysis.apply_census_patch - applies the correction pass's patch (areas to add or replace, areas to remove), so what
--     changes is exactly what the correction lists.
--   owner-direction:ov3-complete-agentic-harness revision 2 (the owner's words verbatim, 17 direction lines);
--   flight-clearance-policy:owner-objective (requires OV3_CONFORMANT only: OV3's work on the owner's objective needs no approval);
--   flight-promise:ov3-harness-census-2 (no owner decision among its obligations).
-- The six procedure bodies are the statements probed on 2026-11-02 (sources ce4cf538; id check bc00f99c, f11d0688; fulfillment gate 8fde4890, 6d20bf47, 2f19a147; patch 02d25ab9, e7694567; selector 636b186c, 13ad6f23; binding 901e22cb, 128fabdc, ce9920d3; definition digests 3d747335).
-- SAFE TO RERUN: before anything is written, each procedure is compared by definition digest (SHA-256 of its definition,
--   surrounding whitespace trimmed). Absent or the same: installed, or re-applied unchanged. Different: the file stops and
--   writes nothing. model.mint_content_artifact adds nothing for a digest and kind it already holds.
--
-- WHERE: the estate database. Run the whole file in one session; the transaction spans the batches.
-- BASE: model.mint_content_artifact sha256:d6f8025a8c5e0d891a50d11df06dc0f2a1785eb7bdd977d0cd45e89eaca2516e. Definition digests:
--   analysis.read_capability_census_sources sha256:b06a0bde24ee8ad05870ff0157fb461f210828180cf2047ecee627c95a6c2815
--   analysis.check_capability_census sha256:1eb70a7b9e2a95cbceea53d303b759c144e3433f8df6688226fbd10e1a92a6bb
--   analysis.check_census_fulfillment sha256:b9e67565c94b9326c4f203a19b1086c795d347e552ce1b65ea65bdef66ba53f7
--   analysis.apply_census_patch sha256:d44b908f60212a8585bd7b17c7eb28b4f999ec6ab8f217a2b7ff516f6f56ae5a
--   analysis.select_census_result sha256:8dff20fd3d50c1e2387cdcf64b8afd5d1552893c63da95c1e4b5e94dfab8beb7
--   analysis.verify_model_binding sha256:638a18390f4d747bb9c1bebf9420d430b53676a1b824a80559e0e22cf478f4fd
-- SELF-TEST (in the transaction): the sources read returns the specification and 17 owner lines, with obligations equal to
--   projects + tasks + lines; the id check passes a census that owns every obligation and fails one that leaves one unowned;
--   the gate fails format-labels ("Alphabetize display labels", claiming everything, judged to fulfill nothing), counts no
--   claim a judgment gives to an area that does not make it, and passes fulfilled claims; the patch removes, replaces and
--   adds; the selector keeps the first round that passed; a receipt naming a provider nobody selected violates the binding and
--   one naming the selected provider honors it; the installed definitions match their digests. Otherwise nothing is kept.
-- RESULT SETS: base; installed; minted; self_test; readback.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @ws nvarchar(4)=NCHAR(9)+NCHAR(10)+NCHAR(13)+NCHAR(32);
DECLARE @installed varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),OBJECT_DEFINITION(OBJECT_ID(N'model.mint_content_artifact')) COLLATE Latin1_General_100_BIN2_UTF8)),2));
DECLARE @p0 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.read_capability_census_sources'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@p1 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.check_capability_census'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@p2 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.check_census_fulfillment'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@p3 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.apply_census_patch'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@p4 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.select_census_result'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@p5 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.verify_model_binding'))) COLLATE Latin1_General_100_BIN2_UTF8)),2));
SELECT N'base' AS result_set,@installed AS installed_digest,'sha256:d6f8025a8c5e0d891a50d11df06dc0f2a1785eb7bdd977d0cd45e89eaca2516e' AS expected_base,CASE WHEN @p0 IS NULL THEN N'absent' WHEN @p0='sha256:b06a0bde24ee8ad05870ff0157fb461f210828180cf2047ecee627c95a6c2815' THEN N'same' ELSE N'DIFFERENT' END AS read_capability_census_sources,CASE WHEN @p1 IS NULL THEN N'absent' WHEN @p1='sha256:1eb70a7b9e2a95cbceea53d303b759c144e3433f8df6688226fbd10e1a92a6bb' THEN N'same' ELSE N'DIFFERENT' END AS check_capability_census,CASE WHEN @p2 IS NULL THEN N'absent' WHEN @p2='sha256:b9e67565c94b9326c4f203a19b1086c795d347e552ce1b65ea65bdef66ba53f7' THEN N'same' ELSE N'DIFFERENT' END AS check_census_fulfillment,CASE WHEN @p3 IS NULL THEN N'absent' WHEN @p3='sha256:d44b908f60212a8585bd7b17c7eb28b4f999ec6ab8f217a2b7ff516f6f56ae5a' THEN N'same' ELSE N'DIFFERENT' END AS apply_census_patch,CASE WHEN @p4 IS NULL THEN N'absent' WHEN @p4='sha256:8dff20fd3d50c1e2387cdcf64b8afd5d1552893c63da95c1e4b5e94dfab8beb7' THEN N'same' ELSE N'DIFFERENT' END AS select_census_result,CASE WHEN @p5 IS NULL THEN N'absent' WHEN @p5='sha256:638a18390f4d747bb9c1bebf9420d430b53676a1b824a80559e0e22cf478f4fd' THEN N'same' ELSE N'DIFFERENT' END AS verify_model_binding;
IF @installed IS NULL OR @installed<>'sha256:d6f8025a8c5e0d891a50d11df06dc0f2a1785eb7bdd977d0cd45e89eaca2516e' OR (@p0 IS NOT NULL AND @p0<>'sha256:b06a0bde24ee8ad05870ff0157fb461f210828180cf2047ecee627c95a6c2815') OR (@p1 IS NOT NULL AND @p1<>'sha256:1eb70a7b9e2a95cbceea53d303b759c144e3433f8df6688226fbd10e1a92a6bb') OR (@p2 IS NOT NULL AND @p2<>'sha256:b9e67565c94b9326c4f203a19b1086c795d347e552ce1b65ea65bdef66ba53f7') OR (@p3 IS NOT NULL AND @p3<>'sha256:d44b908f60212a8585bd7b17c7eb28b4f999ec6ab8f217a2b7ff516f6f56ae5a') OR (@p4 IS NOT NULL AND @p4<>'sha256:8dff20fd3d50c1e2387cdcf64b8afd5d1552893c63da95c1e4b5e94dfab8beb7') OR (@p5 IS NOT NULL AND @p5<>'sha256:638a18390f4d747bb9c1bebf9420d430b53676a1b824a80559e0e22cf478f4fd')
BEGIN
 RAISERROR(N'OV3_HARNESS_06_BASE_DIFFERS: model.mint_content_artifact is not the reviewed writer, or a census procedure exists with another definition digest. Nothing was written; read it before running this file.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
CREATE OR ALTER PROCEDURE analysis.read_capability_census_sources @input nvarchar(max) AS BEGIN SET NOCOUNT ON; DECLARE @d binary(32)=CONVERT(binary(32),SUBSTRING(JSON_VALUE(@input,N'$.specDigest'),8,64),2); DECLARE @project nvarchar(200)=JSON_VALUE(@input,N'$.projectId'),@dirKind nvarchar(80)=JSON_VALUE(@input,N'$.ownerDirectionKind'); DECLARE @e bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1); DECLARE @ob TABLE(o int IDENTITY(1,1) PRIMARY KEY,id nvarchar(450),kind nvarchar(20),text nvarchar(max)); INSERT @ob(id,kind,text) SELECT N'project:'+p.project_id,N'project',LEFT(CONCAT(p.project_display_name,N': ',ISNULL(p.goal,N'')),400) FROM model.project p ORDER BY p.project_id; INSERT @ob(id,kind,text) SELECT N'task:'+t.project_task_id,N'task',LEFT(CONCAT(t.project_task_description,N': ',ISNULL(t.required_outcome,N'')),400)  FROM model.project_task t JOIN model.project p ON p.project_pk=t.project_pk WHERE p.project_id=@project ORDER BY t.project_task_id; DECLARE @dir nvarchar(max),@dirDigest nvarchar(80); SELECT TOP (1) @dir=CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8),@dirDigest=N'sha256:'+LOWER(CONVERT(varchar(64),a.content_digest,2))  FROM model.content_artifact a JOIN source.content_object co ON co.content_digest=a.content_digest WHERE a.artifact_kind=@dirKind COLLATE Latin1_General_100_BIN2  ORDER BY a.registered_date DESC,a.content_artifact_pk DESC; INSERT @ob(id,kind,text) SELECT N'owner:'+CONVERT(nvarchar(10),ROW_NUMBER() OVER (ORDER BY l.ordinal)),N'owner',LEFT(SUBSTRING(l.value,3,4000),1000)  FROM STRING_SPLIT(ISNULL(@dir,N''),NCHAR(10),1) l WHERE LEFT(l.value,2)=N'> ' AND LEFT(l.value,13)<>N'> - the owner' ORDER BY l.ordinal; DECLARE @obl nvarchar(max)=(SELECT id,text FROM @ob ORDER BY o FOR JSON PATH); SELECT (SELECT CASE WHEN co.content_object_pk IS NULL THEN 0 ELSE 1 END AS found,co.byte_length AS bytes,  CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8) AS text,  (SELECT STRING_AGG(CONVERT(nvarchar(max),c.capability_id),N', ') WITHIN GROUP (ORDER BY c.capability_id) FROM model.capability c    JOIN model.identity_namespace n ON n.namespace_pk=c.namespace_pk JOIN model.estate_capability ec ON ec.capability_pk=c.capability_pk AND ec.estate_model_pk=@e    WHERE n.namespace_id=N'sidefx:capabilities') AS capabilityIds,  @obl AS obligations,(SELECT COUNT(*) FROM @ob) AS obligationCount,(SELECT COUNT(*) FROM @ob WHERE kind=N'project') AS projectCount,  (SELECT COUNT(*) FROM @ob WHERE kind=N'task') AS taskCount,(SELECT COUNT(*) FROM @ob WHERE kind=N'owner') AS directionCount,@dirDigest AS ownerDirectionDigest  FROM (SELECT 1 AS one) x LEFT JOIN source.content_object co ON co.content_digest=@d FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) AS value; END;
GO
CREATE OR ALTER PROCEDURE analysis.check_capability_census @input nvarchar(max) AS BEGIN SET NOCOUNT ON; DECLARE @t nvarchar(max)=(SELECT [value] FROM OPENJSON(@input) WHERE [key]=N'censusText'); DECLARE @ot nvarchar(max)=(SELECT [value] FROM OPENJSON(@input) WHERE [key]=N'obligationsText'); DECLARE @req nvarchar(4000)=ISNULL(JSON_VALUE(@input,N'$.requiredCoverage'),N''),@spec nvarchar(80)=JSON_VALUE(@input,N'$.specDigest'); DECLARE @max int=ISNULL(TRY_CONVERT(int,JSON_VALUE(@input,N'$.maxAreas')),30); DECLARE @ob TABLE(id nvarchar(450) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,text nvarchar(max)); IF ISJSON(@ot)=1 INSERT @ob(id,text) SELECT x.id,x.text FROM (SELECT j.id,j.text,ROW_NUMBER() OVER (PARTITION BY j.id ORDER BY (SELECT NULL)) AS rn   FROM OPENJSON(@ot) WITH (id nvarchar(450) N'$.id',text nvarchar(max) N'$.text') j WHERE j.id IS NOT NULL) x WHERE x.rn=1; DECLARE @a TABLE(o int PRIMARY KEY,capability_id nvarchar(400),name nvarchar(400),responsibility nvarchar(max),covers nvarchar(max),answers nvarchar(max),existing nvarchar(max),answers_ok nvarchar(max),existing_ok nvarchar(max)); IF ISJSON(@t)=1 INSERT @a(o,capability_id,name,responsibility,covers,answers,existing) SELECT CONVERT(int,x.[key]),j.capabilityId,j.name,j.responsibility,j.covers,j.answers,j.existing FROM OPENJSON(@t,N'$.areas') x  CROSS APPLY OPENJSON(x.[value]) WITH (capabilityId nvarchar(400) N'$.capabilityId',name nvarchar(400) N'$.name',responsibility nvarchar(max) N'$.responsibility',   covers nvarchar(max) N'$.covers' AS JSON,answers nvarchar(max) N'$.answers' AS JSON,existing nvarchar(max) N'$.existingCapabilities' AS JSON) j WHERE x.[type]=5; UPDATE a SET answers_ok=ISNULL((SELECT N'['+STRING_AGG(N'"'+STRING_ESCAPE(CONVERT(nvarchar(450),s.[value]),'json')+N'"',N',')+N']' FROM OPENJSON(ISNULL(a.answers,N'[]')) s   WHERE EXISTS (SELECT 1 FROM @ob b WHERE b.id=CONVERT(nvarchar(450),s.[value]) COLLATE Latin1_General_100_BIN2)),N'[]'),  existing_ok=ISNULL((SELECT N'['+STRING_AGG(N'"'+STRING_ESCAPE(CONVERT(nvarchar(400),e.[value]),'json')+N'"',N',')+N']' FROM OPENJSON(ISNULL(a.existing,N'[]')) e   WHERE EXISTS (SELECT 1 FROM model.capability c WHERE c.capability_id=CONVERT(nvarchar(400),e.[value]) COLLATE DATABASE_DEFAULT)),N'[]') FROM @a a; DECLARE @n int=(SELECT COUNT(*) FROM @a),@m int=(SELECT COUNT(*) FROM @ob); DECLARE @invalid nvarchar(max)=(SELECT STRING_AGG(ISNULL(capability_id,N'(none)'),N', ') FROM @a WHERE capability_id IS NULL OR capability_id COLLATE Latin1_General_100_BIN2 NOT LIKE N'[0-9a-z]%' OR capability_id COLLATE Latin1_General_100_BIN2 LIKE N'%[^-.0-9a-z]%'); DECLARE @dup nvarchar(max)=(SELECT STRING_AGG(d.capability_id,N', ') FROM (SELECT capability_id FROM @a GROUP BY capability_id HAVING COUNT(*)>1) d); DECLARE @incomplete nvarchar(max)=(SELECT STRING_AGG(ISNULL(capability_id,N'(none)'),N', ') FROM @a WHERE NULLIF(TRIM(ISNULL(name,N'')),N'') IS NULL OR NULLIF(TRIM(ISNULL(responsibility,N'')),N'') IS NULL OR answers_ok=N'[]'); DECLARE @missing nvarchar(max)=(SELECT STRING_AGG(r.v,N', ') FROM (SELECT LTRIM(RTRIM(value)) AS v FROM STRING_SPLIT(@req,N',') WHERE LTRIM(RTRIM(value))<>N'') r  WHERE NOT EXISTS (SELECT 1 FROM @a CROSS APPLY OPENJSON(ISNULL(covers,N'[]')) c WHERE c.[value]=r.v COLLATE DATABASE_DEFAULT)); DECLARE @un TABLE(id nvarchar(450) PRIMARY KEY,text nvarchar(max)); INSERT @un(id,text) SELECT b.id,b.text FROM @ob b WHERE NOT EXISTS (SELECT 1 FROM @a CROSS APPLY OPENJSON(answers_ok) k WHERE CONVERT(nvarchar(450),k.[value]) COLLATE Latin1_General_100_BIN2=b.id); DECLARE @u int=(SELECT COUNT(*) FROM @un); DECLARE @unanswered nvarchar(max)=(SELECT STRING_AGG(id,N', ') WITHIN GROUP (ORDER BY id) FROM @un); DECLARE @droppedAnswers nvarchar(max)=(SELECT STRING_AGG(u.v,N', ') FROM (SELECT DISTINCT CONVERT(nvarchar(450),s.[value]) AS v FROM @a CROSS APPLY OPENJSON(ISNULL(answers,N'[]')) s  WHERE NOT EXISTS (SELECT 1 FROM OPENJSON(answers_ok) k WHERE k.[value]=s.[value])) u); DECLARE @droppedCaps nvarchar(max)=(SELECT STRING_AGG(u.v,N', ') FROM (SELECT DISTINCT CONVERT(nvarchar(400),e.[value]) AS v FROM @a CROSS APPLY OPENJSON(ISNULL(existing,N'[]')) e  WHERE NOT EXISTS (SELECT 1 FROM OPENJSON(existing_ok) k WHERE k.[value]=e.[value])) u); DECLARE @status nvarchar(40)=CASE WHEN ISJSON(@t)<>1 THEN N'NOT_JSON' WHEN @m>0 AND @n BETWEEN 1 AND @max AND @invalid IS NULL AND @dup IS NULL AND @incomplete IS NULL AND @missing IS NULL AND @u=0 THEN N'CENSUS_READY' ELSE N'CENSUS_INVALID' END; DECLARE @nl nchar(1)=NCHAR(10); DECLARE @feedback nvarchar(max)=CASE WHEN @status=N'CENSUS_READY' AND @droppedAnswers IS NULL AND @droppedCaps IS NULL THEN N'No defects.' ELSE CONCAT(N'Defects to fix:',  CASE WHEN ISJSON(@t)<>1 THEN @nl+N'- The answer was not one JSON object.' ELSE N'' END,  CASE WHEN @n>@max THEN CONCAT(@nl,N'- The census has ',@n,N' areas; at most ',@max,N' are allowed. Merge areas.') WHEN @n=0 AND ISJSON(@t)=1 THEN @nl+N'- The census has no areas.' ELSE N'' END,  CASE WHEN @invalid IS NOT NULL THEN @nl+N'- Invalid capability ids (lowercase ASCII letters, digits, dots and hyphens only): '+@invalid ELSE N'' END,  CASE WHEN @dup IS NOT NULL THEN @nl+N'- Duplicate capability ids: '+@dup ELSE N'' END,  CASE WHEN @incomplete IS NOT NULL THEN @nl+N'- Areas missing a name, a responsibility or a valid answer: '+@incomplete ELSE N'' END,  CASE WHEN @missing IS NOT NULL THEN @nl+N'- Required concerns no area covers: '+@missing ELSE N'' END,  CASE WHEN @u>0 THEN @nl+N'- Obligations no area answers (give each an owning area):'+@nl+(SELECT STRING_AGG(CONVERT(nvarchar(max),N'  '+id+N': '+LEFT(text,300)),@nl) WITHIN GROUP (ORDER BY id) FROM @un) ELSE N'' END,  CASE WHEN @droppedAnswers IS NOT NULL THEN @nl+N'- Answers that are not obligation ids were removed: '+@droppedAnswers ELSE N'' END,  CASE WHEN @droppedCaps IS NOT NULL THEN @nl+N'- Capability ids the estate does not hold were removed: '+@droppedCaps ELSE N'' END) END; DECLARE @product nvarchar(400)=CASE WHEN ISJSON(@t)=1 THEN JSON_VALUE(@t,N'$.product') END; DECLARE @census nvarchar(max)=(SELECT @product AS product,@spec AS specDigest,@m AS obligationCount,JSON_QUERY(ISNULL((SELECT capability_id AS capabilityId,name,responsibility,JSON_QUERY(ISNULL(covers,N'[]')) AS covers,  JSON_QUERY(answers_ok) AS answers,JSON_QUERY(existing_ok) AS existingCapabilities FROM @a ORDER BY o FOR JSON PATH),N'[]')) AS areas FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); DECLARE @cell TABLE(o int PRIMARY KEY,line nvarchar(max)); INSERT @cell SELECT o,CONCAT(N'| ',o+1,N' | `',capability_id,N'` | ',REPLACE(REPLACE(ISNULL(name,N''),N'|',N'/'),@nl,N' '),N' | ',REPLACE(REPLACE(ISNULL(responsibility,N''),N'|',N'/'),@nl,N' '),N' | ',  ISNULL((SELECT STRING_AGG(CONVERT(nvarchar(max),c.[value]),N', ') FROM OPENJSON(ISNULL(covers,N'[]')) c),N''),N' | ',ISNULL((SELECT STRING_AGG(CONVERT(nvarchar(max),k.[value]),N', ') FROM OPENJSON(answers_ok) k),N''),N' | ',  ISNULL((SELECT STRING_AGG(CONVERT(nvarchar(max),k.[value]),N', ') FROM OPENJSON(existing_ok) k),N''),N' |') FROM @a; DECLARE @md nvarchar(max)=CONCAT(N'# Capability-area census: ',ISNULL(@product,N'(no product)'),@nl,@nl,  N'Written by ask-model from specification ',ISNULL(@spec,N'(unnamed)'),N' and checked by the flight against every recorded obligation: ',@status,N', ',@n,N' areas, ',@m-@u,N' of ',@m,N' obligations owned',  CASE WHEN @missing IS NULL THEN N', every required concern covered.' ELSE N', missing '+@missing+N'.' END,@nl,@nl,  CASE WHEN @u>0 THEN N'Unowned obligations: '+@unanswered+N'.'+@nl+@nl ELSE N'' END,  CASE WHEN @droppedAnswers IS NULL AND @droppedCaps IS NULL THEN N'' ELSE CONCAT(N'Removed because the lists or the estate do not hold them: ',ISNULL(@droppedCaps,N''),CASE WHEN @droppedCaps IS NOT NULL AND @droppedAnswers IS NOT NULL THEN N'; ' ELSE N'' END,ISNULL(@droppedAnswers,N''),N'.',@nl,@nl) END,  N'| # | Capability id | Area | Responsibility | Covers | Owns obligations | Extends or reuses |',@nl,N'| --- | --- | --- | --- | --- | --- | --- |',@nl,  ISNULL((SELECT STRING_AGG(line,@nl) WITHIN GROUP (ORDER BY o) FROM @cell),N''),@nl); SELECT (SELECT 1 AS ran,@status AS status,@n AS areaCount,@m AS obligationCount,@u AS unansweredCount,@unanswered AS unanswered,@invalid AS invalidIds,@dup AS duplicateIds,@incomplete AS incompleteAreas,  @missing AS missingCoverage,@droppedAnswers AS droppedAnswers,@droppedCaps AS droppedCapabilities,@feedback AS feedback,@census AS censusJson,@md AS markdown FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) AS value; END;
GO
CREATE OR ALTER PROCEDURE analysis.check_census_fulfillment @input nvarchar(max) AS BEGIN SET NOCOUNT ON; DECLARE @t nvarchar(max)=(SELECT [value] FROM OPENJSON(@input) WHERE [key]=N'censusText'); DECLARE @ot nvarchar(max)=(SELECT [value] FROM OPENJSON(@input) WHERE [key]=N'obligationsText'); DECLARE @jt nvarchar(max)=(SELECT [value] FROM OPENJSON(@input) WHERE [key]=N'judgmentText'); DECLARE @idFeedback nvarchar(max)=(SELECT [value] FROM OPENJSON(@input) WHERE [key]=N'idFeedback'); DECLARE @idStatus nvarchar(40)=JSON_VALUE(@input,N'$.idStatus'),@nl nchar(1)=NCHAR(10); DECLARE @ob TABLE(id nvarchar(450) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,text nvarchar(max)); IF ISJSON(@ot)=1 INSERT @ob(id,text) SELECT x.id,x.text FROM (SELECT j.id,j.text,ROW_NUMBER() OVER (PARTITION BY j.id ORDER BY (SELECT NULL)) AS rn   FROM OPENJSON(@ot) WITH (id nvarchar(450) N'$.id',text nvarchar(max) N'$.text') j WHERE j.id IS NOT NULL) x WHERE x.rn=1; DECLARE @a TABLE(o int PRIMARY KEY,capability_id nvarchar(400) COLLATE Latin1_General_100_BIN2,name nvarchar(400),responsibility nvarchar(max),covers nvarchar(max),answers nvarchar(max),existing nvarchar(max)); IF ISJSON(@t)=1 INSERT @a(o,capability_id,name,responsibility,covers,answers,existing) SELECT CONVERT(int,x.[key]),j.capabilityId,j.name,j.responsibility,j.covers,j.answers,j.existing FROM OPENJSON(@t,N'$.areas') x  CROSS APPLY OPENJSON(x.[value]) WITH (capabilityId nvarchar(400) N'$.capabilityId',name nvarchar(400) N'$.name',responsibility nvarchar(max) N'$.responsibility',   covers nvarchar(max) N'$.covers' AS JSON,answers nvarchar(max) N'$.answers' AS JSON,existing nvarchar(max) N'$.existingCapabilities' AS JSON) j WHERE x.[type]=5; DECLARE @claim TABLE(capability_id nvarchar(400) COLLATE Latin1_General_100_BIN2,obligation_id nvarchar(450) COLLATE Latin1_General_100_BIN2,PRIMARY KEY(capability_id,obligation_id)); INSERT @claim SELECT DISTINCT a.capability_id,CONVERT(nvarchar(450),s.[value]) FROM @a a CROSS APPLY OPENJSON(ISNULL(a.answers,N'[]')) s  WHERE a.capability_id IS NOT NULL AND EXISTS (SELECT 1 FROM @ob b WHERE b.id=CONVERT(nvarchar(450),s.[value])); DECLARE @v TABLE(obligation_id nvarchar(450) COLLATE Latin1_General_100_BIN2,fulfilled_by nvarchar(max),reason nvarchar(max)); IF ISJSON(@jt)=1 INSERT @v SELECT j.obligationId,j.fulfilledBy,j.reason FROM OPENJSON(@jt,N'$.verdicts') WITH (obligationId nvarchar(450) N'$.obligationId',   fulfilledBy nvarchar(max) N'$.fulfilledBy' AS JSON,reason nvarchar(max) N'$.reason') j WHERE j.obligationId IS NOT NULL; DECLARE @ok TABLE(capability_id nvarchar(400) COLLATE Latin1_General_100_BIN2,obligation_id nvarchar(450) COLLATE Latin1_General_100_BIN2,PRIMARY KEY(capability_id,obligation_id)); INSERT @ok SELECT DISTINCT c.capability_id,c.obligation_id FROM @v v CROSS APPLY OPENJSON(ISNULL(v.fulfilled_by,N'[]')) f  JOIN @claim c ON c.obligation_id=v.obligation_id AND c.capability_id=CONVERT(nvarchar(400),f.[value]); DECLARE @m int=(SELECT COUNT(*) FROM @ob),@n int=(SELECT COUNT(*) FROM @a); DECLARE @un TABLE(id nvarchar(450) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,text nvarchar(max),reason nvarchar(max)); INSERT @un SELECT b.id,b.text,(SELECT TOP (1) v.reason FROM @v v WHERE v.obligation_id=b.id) FROM @ob b WHERE NOT EXISTS (SELECT 1 FROM @ok k WHERE k.obligation_id=b.id); DECLARE @u int=(SELECT COUNT(*) FROM @un),@unjudged int=(SELECT COUNT(*) FROM @ob b WHERE NOT EXISTS (SELECT 1 FROM @v v WHERE v.obligation_id=b.id)); DECLARE @unfulfilled nvarchar(max)=(SELECT STRING_AGG(CONVERT(nvarchar(max),id),N', ') WITHIN GROUP (ORDER BY id) FROM @un); DECLARE @rejected int=(SELECT COUNT(*) FROM @claim c WHERE NOT EXISTS (SELECT 1 FROM @ok k WHERE k.capability_id=c.capability_id AND k.obligation_id=c.obligation_id)); DECLARE @rej nvarchar(max)=(SELECT STRING_AGG(CONVERT(nvarchar(max),N'  '+(r.capability_id COLLATE DATABASE_DEFAULT)+N' -> '+(r.ids COLLATE DATABASE_DEFAULT)),@nl) WITHIN GROUP (ORDER BY r.capability_id) FROM (SELECT c.capability_id,   STRING_AGG(CONVERT(nvarchar(max),c.obligation_id),N', ') WITHIN GROUP (ORDER BY c.obligation_id) AS ids FROM @claim c   WHERE NOT EXISTS (SELECT 1 FROM @ok k WHERE k.capability_id=c.capability_id AND k.obligation_id=c.obligation_id) GROUP BY c.capability_id) r); DECLARE @status nvarchar(40)=CASE WHEN ISJSON(@t)<>1 OR ISJSON(@jt)<>1 THEN N'NOT_JSON' WHEN ISNULL(@idStatus,N'')=N'CENSUS_READY' AND @m>0 AND @u=0 THEN N'CENSUS_READY' ELSE N'CENSUS_INVALID' END; DECLARE @idDefects nvarchar(max)=CASE WHEN ISNULL(@idFeedback,N'')=N'No defects.' THEN NULL ELSE NULLIF(REPLACE(ISNULL(@idFeedback,N''),N'Defects to fix:'+@nl,N''),N'') END; DECLARE @feedback nvarchar(max)=CASE WHEN @status=N'CENSUS_READY' AND @rejected=0 AND @idDefects IS NULL THEN N'No defects.' ELSE CONCAT(N'Defects to fix:',  CASE WHEN ISJSON(@jt)<>1 THEN @nl+N'- The fulfillment judgment was not one JSON object.' ELSE N'' END,  CASE WHEN @idDefects IS NOT NULL THEN @nl+@idDefects ELSE N'' END,  CASE WHEN @u>0 THEN @nl+N'- Obligations no area fulfills. Give each one an area whose responsibility does what the obligation requires, by rewriting an area or adding one; listing its id is not enough:'+@nl+   (SELECT STRING_AGG(CONVERT(nvarchar(max),N'  '+(id COLLATE DATABASE_DEFAULT)+N': '+LEFT(text,300)+CASE WHEN reason IS NOT NULL THEN N' (fulfillment check: '+LEFT(reason,300)+N')' ELSE N'' END),@nl) WITHIN GROUP (ORDER BY id) FROM @un) ELSE N'' END,  CASE WHEN @rejected>0 THEN @nl+N'- Claims the fulfillment check rejected, because the area''s responsibility does not do what the obligation requires (remove each one, or rewrite the area so that it does):'+@nl+@rej ELSE N'' END) END; DECLARE @census nvarchar(max)=(SELECT JSON_VALUE(@t,N'$.product') AS product,JSON_VALUE(@t,N'$.specDigest') AS specDigest,@m AS obligationCount,@m-@u AS fulfilledCount,  JSON_QUERY(ISNULL((SELECT a.capability_id AS capabilityId,a.name,a.responsibility,JSON_QUERY(ISNULL(a.covers,N'[]')) AS covers,   JSON_QUERY(ISNULL((SELECT N'['+STRING_AGG(N'"'+STRING_ESCAPE(CONVERT(nvarchar(max),k.obligation_id),'json')+N'"',N',') WITHIN GROUP (ORDER BY k.obligation_id)+N']' FROM @ok k WHERE k.capability_id=a.capability_id),N'[]')) AS answers,   JSON_QUERY(ISNULL(a.existing,N'[]')) AS existingCapabilities FROM @a a ORDER BY a.o FOR JSON PATH),N'[]')) AS areas,  JSON_QUERY(ISNULL((SELECT b.id AS obligationId,JSON_QUERY(ISNULL((SELECT N'['+STRING_AGG(N'"'+STRING_ESCAPE(CONVERT(nvarchar(max),k.capability_id),'json')+N'"',N',') WITHIN GROUP (ORDER BY k.capability_id)+N']'   FROM @ok k WHERE k.obligation_id=b.id),N'[]')) AS fulfilledBy,(SELECT TOP (1) v.reason FROM @v v WHERE v.obligation_id=b.id) AS reason FROM @ob b ORDER BY b.id FOR JSON PATH),N'[]')) AS fulfillment  FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); DECLARE @cell TABLE(o int PRIMARY KEY,line nvarchar(max)); INSERT @cell SELECT a.o,CONCAT(N'| ',a.o+1,N' | `',a.capability_id COLLATE DATABASE_DEFAULT,N'` | ',REPLACE(REPLACE(ISNULL(a.name,N''),N'|',N'/'),@nl,N' '),N' | ',REPLACE(REPLACE(ISNULL(a.responsibility,N''),N'|',N'/'),@nl,N' '),N' | ',  ISNULL((SELECT STRING_AGG(CONVERT(nvarchar(max),c.[value]),N', ') FROM OPENJSON(ISNULL(a.covers,N'[]')) c),N''),N' | ',  ISNULL((SELECT STRING_AGG(CONVERT(nvarchar(max),k.obligation_id COLLATE DATABASE_DEFAULT),N', ') WITHIN GROUP (ORDER BY k.obligation_id) FROM @ok k WHERE k.capability_id=a.capability_id),N''),N' | ',  ISNULL((SELECT STRING_AGG(CONVERT(nvarchar(max),e.[value]),N', ') FROM OPENJSON(ISNULL(a.existing,N'[]')) e),N''),N' |') FROM @a a; DECLARE @fl TABLE(id nvarchar(450) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,line nvarchar(max)); INSERT @fl SELECT b.id,CONCAT(N'| `',b.id COLLATE DATABASE_DEFAULT,N'` | ',ISNULL((SELECT STRING_AGG(CONVERT(nvarchar(max),N'`'+(k.capability_id COLLATE DATABASE_DEFAULT)+N'`'),N', ') WITHIN GROUP (ORDER BY k.capability_id) FROM @ok k WHERE k.obligation_id=b.id),N'(none)'),N' | ',  REPLACE(REPLACE(ISNULL((SELECT TOP (1) v.reason FROM @v v WHERE v.obligation_id=b.id),N''),N'|',N'/'),@nl,N' '),N' |') FROM @ob b; DECLARE @md nvarchar(max)=CONCAT(N'# Capability-area census: ',ISNULL(JSON_VALUE(@t,N'$.product'),N'(no product)'),@nl,@nl,  N'Written by ask-model from specification ',ISNULL(JSON_VALUE(@t,N'$.specDigest'),N'(unnamed)'),N', then checked twice: that every obligation id is answered (',ISNULL(@idStatus,N'not run'),  N'), and, separately, that each area''s responsibility does what each obligation it claims requires (',@status,N'). ',@m-@u,N' of ',@m,N' obligations fulfilled; ',@rejected,N' claims rejected; ',@n,N' areas.',@nl,@nl,  CASE WHEN @u>0 THEN N'Unfulfilled obligations: '+@unfulfilled+N'.'+@nl+@nl ELSE N'' END,  N'| # | Capability id | Area | Responsibility | Covers | Fulfills obligations | Extends or reuses |',@nl,N'| --- | --- | --- | --- | --- | --- | --- |',@nl,  ISNULL((SELECT STRING_AGG(line,@nl) WITHIN GROUP (ORDER BY o) FROM @cell),N''),@nl,@nl,N'## Fulfillment, per obligation',@nl,@nl,  N'| Obligation | Fulfilled by | Reason the fulfillment check gave |',@nl,N'| --- | --- | --- |',@nl,ISNULL((SELECT STRING_AGG(line,@nl) WITHIN GROUP (ORDER BY id) FROM @fl),N''),@nl); SELECT (SELECT 1 AS ran,@status AS status,@idStatus AS idStatus,@n AS areaCount,@m AS obligationCount,@m-@u AS fulfilledCount,@u AS unfulfilledCount,@unfulfilled AS unfulfilled,  @rejected AS rejectedClaims,@unjudged AS unjudgedObligations,@feedback AS feedback,@census AS censusJson,@md AS markdown FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) AS value; END;
GO
CREATE OR ALTER PROCEDURE analysis.apply_census_patch @input nvarchar(max) AS BEGIN SET NOCOUNT ON; DECLARE @t nvarchar(max)=(SELECT [value] FROM OPENJSON(@input) WHERE [key]=N'censusText'); DECLARE @pt nvarchar(max)=(SELECT [value] FROM OPENJSON(@input) WHERE [key]=N'patchText'); DECLARE @ok int=CASE WHEN ISJSON(@pt)=1 THEN 1 ELSE 0 END; DECLARE @rm TABLE(capability_id nvarchar(400) COLLATE Latin1_General_100_BIN2 PRIMARY KEY); IF @ok=1 INSERT @rm SELECT DISTINCT CONVERT(nvarchar(400),r.[value]) FROM OPENJSON(@pt,N'$.remove') r WHERE r.[type]=1; DECLARE @a TABLE(o int IDENTITY(1,1) PRIMARY KEY,capability_id nvarchar(400) COLLATE Latin1_General_100_BIN2,area nvarchar(max)); IF ISJSON(@t)=1 INSERT @a(capability_id,area) SELECT JSON_VALUE(x.[value],N'$.capabilityId'),x.[value] FROM OPENJSON(@t,N'$.areas') x  WHERE x.[type]=5 AND NOT EXISTS (SELECT 1 FROM @rm r WHERE r.capability_id=JSON_VALUE(x.[value],N'$.capabilityId')) ORDER BY CONVERT(int,x.[key]); DECLARE @p TABLE(o int PRIMARY KEY,capability_id nvarchar(400) COLLATE Latin1_General_100_BIN2,area nvarchar(max)); IF @ok=1 INSERT @p SELECT CONVERT(int,x.[key]),JSON_VALUE(x.[value],N'$.capabilityId'),x.[value] FROM OPENJSON(@pt,N'$.areas') x WHERE x.[type]=5; DECLARE @replaced int=(SELECT COUNT(*) FROM @a a WHERE EXISTS (SELECT 1 FROM @p p WHERE p.capability_id=a.capability_id)); UPDATE a SET area=(SELECT TOP (1) p.area FROM @p p WHERE p.capability_id=a.capability_id ORDER BY p.o DESC) FROM @a a WHERE EXISTS (SELECT 1 FROM @p p WHERE p.capability_id=a.capability_id); DECLARE @added int=(SELECT COUNT(*) FROM @p p WHERE NOT EXISTS (SELECT 1 FROM @a a WHERE a.capability_id=p.capability_id)); INSERT @a(capability_id,area) SELECT p.capability_id,p.area FROM @p p WHERE NOT EXISTS (SELECT 1 FROM @a a WHERE a.capability_id=p.capability_id) ORDER BY p.o; DECLARE @census nvarchar(max)=CONCAT(N'{"product":',ISNULL(N'"'+STRING_ESCAPE(JSON_VALUE(@t,N'$.product'),'json')+N'"',N'null'),N',"areas":[',  ISNULL((SELECT STRING_AGG(CONVERT(nvarchar(max),area),N',') WITHIN GROUP (ORDER BY o) FROM @a),N''),N']}'); SELECT (SELECT 1 AS ran,@ok AS patchIsJson,(SELECT COUNT(*) FROM @rm) AS removed,@replaced AS replaced,@added AS added,(SELECT COUNT(*) FROM @a) AS areaCount,  @census AS census FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) AS value; END;
GO
CREATE OR ALTER PROCEDURE analysis.select_census_result @input nvarchar(max) AS BEGIN SET NOCOUNT ON; DECLARE @s1 nvarchar(40)=JSON_VALUE(@input,N'$.firstStatus'),@s2 nvarchar(40)=JSON_VALUE(@input,N'$.secondStatus'); DECLARE @r int=CASE WHEN @s1=N'CENSUS_READY' THEN 1 WHEN @s2=N'CENSUS_READY' THEN 2 END; DECLARE @k nvarchar(10)=CASE WHEN @r=1 THEN N'first' ELSE N'second' END; SELECT (SELECT 1 AS ran,CASE WHEN @r IS NULL THEN ISNULL(@s2,N'CENSUS_INVALID') ELSE N'CENSUS_READY' END AS status,@r AS round,  (SELECT [value] FROM OPENJSON(@input) WHERE [key]=@k+N'Census') AS censusJson,(SELECT [value] FROM OPENJSON(@input) WHERE [key]=@k+N'Markdown') AS markdown,  (SELECT [value] FROM OPENJSON(@input) WHERE [key]=@k+N'Feedback') AS feedback FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) AS value; END;
GO
CREATE OR ALTER PROCEDURE analysis.verify_model_binding @input nvarchar(max) AS BEGIN SET NOCOUNT ON; DECLARE @e bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1); DECLARE @defs TABLE(kind nvarchar(64) COLLATE DATABASE_DEFAULT,id nvarchar(400) COLLATE DATABASE_DEFAULT,sem nvarchar(max)); INSERT @defs(kind,id,sem) SELECT x.object_kind,x.declared_id,JSON_QUERY(x.body,N'$.semantics') FROM (  SELECT CONVERT(nvarchar(64),so.object_kind) COLLATE DATABASE_DEFAULT AS object_kind,CONVERT(nvarchar(400),so.declared_id) COLLATE DATABASE_DEFAULT AS declared_id,   CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8) AS body,   ROW_NUMBER() OVER (PARTITION BY so.semantic_object_pk ORDER BY d.semantic_object_definition_pk DESC) AS rn  FROM model.semantic_object so JOIN model.identity_namespace n ON n.namespace_pk=so.namespace_pk  JOIN model.semantic_object_definition d ON d.semantic_object_pk=so.semantic_object_pk  JOIN model.estate_definition ed ON ed.semantic_object_definition_pk=d.semantic_object_definition_pk AND ed.estate_model_pk=@e  JOIN source.content_object co ON co.content_object_pk=d.canonical_content_pk  WHERE n.namespace_id=N'sidefx:model-providers') x WHERE x.rn=1; DECLARE @c TABLE(o int PRIMARY KEY,step nvarchar(200),role nvarchar(400),provider nvarchar(400),model nvarchar(400),expected_provider nvarchar(400),expected_model nvarchar(400)); INSERT @c(o,step,role,provider,model) SELECT CONVERT(int,x.[key]),j.step,j.role,j.provider,j.model FROM OPENJSON(@input,N'$.calls') x  CROSS APPLY OPENJSON(x.[value]) WITH (step nvarchar(200) N'$.step',role nvarchar(400) N'$.role',provider nvarchar(400) N'$.provider',model nvarchar(400) N'$.model') j WHERE x.[type]=5; UPDATE c SET expected_provider=COALESCE((SELECT JSON_VALUE(sem,N'$.modelProviderId') FROM @defs WHERE kind=N'MODEL_SELECTION' AND id=c.role),  (SELECT JSON_VALUE(sem,N'$.modelProviderId') FROM @defs WHERE kind=N'MODEL_SELECTION' AND id=N'default')) FROM @c c; UPDATE c SET expected_model=(SELECT JSON_VALUE(sem,N'$.model') FROM @defs WHERE kind=N'MODEL_PROVIDER' AND id=c.expected_provider) FROM @c c; DECLARE @n int=(SELECT COUNT(*) FROM @c),@bad int=(SELECT COUNT(*) FROM @c WHERE expected_provider IS NULL OR provider IS NULL OR provider<>expected_provider OR ISNULL(model,N'')<>ISNULL(expected_model,N'')); SELECT (SELECT 1 AS ran,CASE WHEN @n>0 AND @bad=0 THEN N'BINDING_HONORED' ELSE N'BINDING_VIOLATED' END AS status,@n AS calls,@bad AS violations,  JSON_QUERY((SELECT step,role,expected_provider AS expectedProvider,expected_model AS expectedModel,provider AS receiptProvider,model AS receiptModel,   CASE WHEN expected_provider IS NOT NULL AND provider=expected_provider AND ISNULL(model,N'')=ISNULL(expected_model,N'') THEN 1 ELSE 0 END AS honored   FROM @c ORDER BY o FOR JSON PATH,INCLUDE_NULL_VALUES)) AS evidence FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) AS value; END;
GO
GRANT EXECUTE ON OBJECT::analysis.read_capability_census_sources TO sidefx_reader;
GRANT EXECUTE ON OBJECT::analysis.check_capability_census TO sidefx_reader;
GRANT EXECUTE ON OBJECT::analysis.check_census_fulfillment TO sidefx_reader;
GRANT EXECUTE ON OBJECT::analysis.apply_census_patch TO sidefx_reader;
GRANT EXECUTE ON OBJECT::analysis.select_census_result TO sidefx_reader;
GRANT EXECUTE ON OBJECT::analysis.verify_model_binding TO sidefx_reader;
GO
DECLARE @ws nvarchar(4)=NCHAR(9)+NCHAR(10)+NCHAR(13)+NCHAR(32);
DECLARE @v0 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.read_capability_census_sources'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@v1 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.check_capability_census'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@v2 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.check_census_fulfillment'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@v3 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.apply_census_patch'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@v4 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.select_census_result'))) COLLATE Latin1_General_100_BIN2_UTF8)),2)),@v5 varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),TRIM(@ws FROM OBJECT_DEFINITION(OBJECT_ID(N'analysis.verify_model_binding'))) COLLATE Latin1_General_100_BIN2_UTF8)),2));
SELECT N'installed' AS result_set,@v0 AS read_capability_census_sources,@v1 AS check_capability_census,@v2 AS check_census_fulfillment,@v3 AS apply_census_patch,@v4 AS select_census_result,@v5 AS verify_model_binding,CASE WHEN ISNULL(@v0,'')='sha256:b06a0bde24ee8ad05870ff0157fb461f210828180cf2047ecee627c95a6c2815' AND ISNULL(@v1,'')='sha256:1eb70a7b9e2a95cbceea53d303b759c144e3433f8df6688226fbd10e1a92a6bb' AND ISNULL(@v2,'')='sha256:b9e67565c94b9326c4f203a19b1086c795d347e552ce1b65ea65bdef66ba53f7' AND ISNULL(@v3,'')='sha256:d44b908f60212a8585bd7b17c7eb28b4f999ec6ab8f217a2b7ff516f6f56ae5a' AND ISNULL(@v4,'')='sha256:8dff20fd3d50c1e2387cdcf64b8afd5d1552893c63da95c1e4b5e94dfab8beb7' AND ISNULL(@v5,'')='sha256:638a18390f4d747bb9c1bebf9420d430b53676a1b824a80559e0e22cf478f4fd' THEN 1 ELSE 0 END AS matches;
IF NOT (ISNULL(@v0,'')='sha256:b06a0bde24ee8ad05870ff0157fb461f210828180cf2047ecee627c95a6c2815' AND ISNULL(@v1,'')='sha256:1eb70a7b9e2a95cbceea53d303b759c144e3433f8df6688226fbd10e1a92a6bb' AND ISNULL(@v2,'')='sha256:b9e67565c94b9326c4f203a19b1086c795d347e552ce1b65ea65bdef66ba53f7' AND ISNULL(@v3,'')='sha256:d44b908f60212a8585bd7b17c7eb28b4f999ec6ab8f217a2b7ff516f6f56ae5a' AND ISNULL(@v4,'')='sha256:8dff20fd3d50c1e2387cdcf64b8afd5d1552893c63da95c1e4b5e94dfab8beb7' AND ISNULL(@v5,'')='sha256:638a18390f4d747bb9c1bebf9420d430b53676a1b824a80559e0e22cf478f4fd')
BEGIN
 RAISERROR(N'OV3_HARNESS_06_INSTALL_MISMATCH: an installed census procedure does not hold the probed definition; nothing is kept.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
DECLARE @minted TABLE(ordinal int IDENTITY(1,1),value nvarchar(max));
INSERT @minted(value) EXEC model.mint_content_artifact @document=N'{"artifactKind":"owner-direction:ov3-complete-agentic-harness","text":"# Owner direction: ov3-complete-agentic-harness\n\nRetained as owner-direction:ov3-complete-agentic-harness, revision 2. The owner''s words, verbatim, principal 565de6d4-ebcd-408b-9359-04d21dc62183. Each quoted line is one direction; the census owns every one.\n\n## The directions of 2026-11-02\n\n> Whatever needs to be done in SQL, you''ll need to generate a .sql file and I''ll run it. Ultimately, we''re transferring agency to OV3.\n> - the owner, 2026-11-02\n> Is this something that typesafe-model-one can address as it relates to this fuzziness? We want deterministic multi-step task execution through OV3. We don''t want fuzziness or bespokeness for one specific line of work. OV3 needs to become a real agentic harness. Therefore, the way we address this issue needs to be durable.\n> - the owner, 2026-11-02\n> Yes, this is the ultimate problem: \"The objective-loop design rules out elaborate planning, self-improvement, multi-agent consensus, and extra control-plane pieces\". This totally goes against what I''ve asked for. You can see the project tracker history and flights that we''ve flown to transfer agency. Here''s the problem: - The canonical features (gherkin) were never written up and stored durabily in the estate and therefore the wrong design above was implemented. We need to get the OV3 network to write up it''s own features to be a complete agentic harness, which includes (but not limited to): elaborate planning, self-improvement, multi-agent consensus, and extra control-plane pieces. Then we will have OV3 build it''s own future state. That''s the way to go.\n> - the owner, 2026-11-02\n\n## The directions already on record\n\n> Capabilities are created in the database. And the first thing we need to establish when creating capabilities is what providers are needed for that capability. And then those providers also become capabilities that are bound as providers to the root scenario capabilities.\n> - the owner, 2026-10-25 (docs/projects/OV3 Software Engineering Harness.md)\n> We don''t want any bespoke implementation in OV3. That should be purely driven by investigation of what providers are needed in order for that capability to achieve its effects and outcomes.\n> - the owner, 2026-10-25 (docs/projects/OV3 Software Engineering Harness.md)\n> The workers are going to be necessary for delivering the Markdown to the local machine of the user ... but also delivering any test harnesses that they need, such as HTML.\n> - the owner, 2026-10-25 (docs/projects/OV3 Software Engineering Harness.md)\n> The OV3 network needs to be able to also look up open source providers on the internet to propose/suggest leverage (e.g, https://landscape.cncf.io/, github, hugging-face, etc.).\n> - the owner, 2026-10-25 (docs/projects/OV3 Software Engineering Harness.md)\n> The cncf and github is powerful because direct integration is discoverable!\n> - the owner, 2026-10-25 (docs/projects/OV3 Software Engineering Harness.md)\n> All of these decisions will be decided in intentional workflows.\n> - the owner, 2026-10-25 (docs/projects/Provider Capability Registry.md)\n> when I tell you to do something I am giving you authority. I am the owner of this product and the purchaser and owner of this subscription. Do not ever \"give\" me friction. Friction is not what we''re building in the process here.\n> - the owner, 2026-10-23 (docs/projects/Transfer of Agency/flight-process.md)\n\n## 2026-11-02, later: OV3 owns the work\n\n> This is a real gap: \"There''s no confusion about your goal, and you have nothing to clarify. **You give OV3 an objective. OV3 owns the work from there** - assembling the evidence, planning, coordinating specialists, executing, checking the result against your intent, and correcting gaps. That includes building and improving the harness itself. You retain authority over the decisions you reserve.\n> I put the work back on you when I found that none of the 30 census areas explicitly owned specification assembly and asked you to tell OV3 how to fix it. Your direction was already on record. The census check verified five required concerns, but it never checked whether every recorded project obligation had an area responsible for it. That''s how the census passed with a gap.\n> The current flight is paused because its plan explicitly calls for an owner decision. What OV3 should bring to that decision is a census it has already checked against your recorded direction, with gaps it can resolve already addressed. You shouldn''t have to act as the planner or use me as a relay to get it there.\"\n> OV3 network should not asking for my approval to fulfill my request. I need efficiency.\n> - the owner, 2026-11-02, endorsing the quoted assessment\n\n## 2026-11-02, later still: every provider-dependent feature names its verified provider binding\n\n> Yeah, baby. Let''s do this shit right: \"Yes. **I''d make the expected provider binding part of each canonical feature wherever the scenario depends on a provider.** That follows your provider-first direction. OV3 identifies what provider capability it needs, proves that the provider can deliver the required effect, and binds it to the root scenario. The feature references that binding by its estate identity. [Owner direction](C:/lab/ov3-workflow-authority-spec/ov3-agentic-harness/owner-direction.v2.md#L16)\n> The census gives a concrete example. Its scenario should require `ask-model` to use the estate''s declared model selection, return a census that satisfies the schema, and record which provider and model actually answered. A separate selection scenario can say that **given** a binding to `deepseek/deepseek-flash`, the run receipt must identify DeepSeek. That catches an accidental call to Gemini while allowing a future deliberate model change through the binding. [Census provider selection](C:/lab/ov3-workflow-authority-spec/ov3-agentic-harness/README.md#L81)\n> I''d have each provider-dependent scenario answer three questions: **Which declared provider capability does OV3 need? What result must it produce here? What run evidence proves it did so?** A provider OV3 merely expects to use stays a candidate until OV3 verifies it. Discovering, proving, and maintaining those bindings is part of the agency you''re transferring to the network.\"\n> - the owner, 2026-11-02, endorsing the quoted recommendation\n\nThis direction supersedes the stance in docs/projects/objective-agent-loop.md section 2 (\"no need for elaborate planning algorithms, self-improvement policies, multi-agent consensus, or additional control-plane primitives\") and every flight step that asks the owner to approve or decide what the owner did not reserve.\n"}';
INSERT @minted(value) EXEC model.mint_content_artifact @document=N'{"artifactKind":"flight-clearance-policy:owner-objective","text":"{\"contractId\":\"flight-clearance-policy.v1\",\"workClass\":\"owner-objective\",\"requires\":[\"OV3_CONFORMANT\"],\"basis\":\"Owner direction 2026-11-02: \\\"OV3 network should not asking for my approval to fulfill my request. I need efficiency.\\\" and \\\"You give OV3 an objective. OV3 owns the work from there.\\\" A plan of this work class fulfills an objective the owner gave; it clears on the deterministic review alone, with no owner approval. Decisions the owner reserves keep their own work classes and decision points. The default policy foresaw this: \\\"repeated evidence may later declare an OV3-only policy for a bounded work class.\\\"\"}"}';
INSERT @minted(value) EXEC model.mint_content_artifact @document=N'{"artifactKind":"flight-promise:ov3-harness-census-2","text":"{\"contractId\":\"flight-promise.v1\",\"promiseId\":\"ov3-harness-census-2\",\"workClass\":\"owner-objective\",\"statement\":\"OV3 writes the capability-area census of its complete agentic harness from the retained specification, checks that every recorded obligation - each tracker project, each task of the project and each owner direction - is claimed by an area whose stated responsibility actually fulfills it, corrects every defect the checks find, and retains and delivers the checked census, with no owner approval or decision.\",\"obligations\":[{\"obligationId\":\"O1\",\"statement\":\"The tracker records, under OV3''s own authority, the owner''s objective with no owner approval or decision, the agency acceptance test, and flight ov3-harness-census as superseded by this flight; no owner decision is recorded.\",\"evidence\":\"project-tracking COMMITTED\"},{\"obligationId\":\"O2\",\"statement\":\"Every recorded obligation is read from rows, after this flight''s own tracker change.\",\"evidence\":\"analysis.read_capability_census_sources found 1\"},{\"obligationId\":\"O3\",\"statement\":\"OV3 writes the census and checks it twice: every obligation id is answered, and a separate fulfillment check judges whether each area''s responsibility does what each obligation it claims requires.\",\"evidence\":\"ask-model MODEL_RESPONSE_OBTAINED (write, judge); analysis.check_capability_census and analysis.check_census_fulfillment ran\"},{\"obligationId\":\"O4\",\"statement\":\"OV3 corrects every defect both checks found, in up to two rounds, and keeps the first round whose census passes both: every obligation fulfilled by an area that claims it.\",\"evidence\":\"ask-model MODEL_RESPONSE_OBTAINED (correct, judge); analysis.select_census_result CENSUS_READY\"},{\"obligationId\":\"O5\",\"statement\":\"Every model call honored the estate''s declared provider binding (MODEL_SELECTION of its role, else default), proved by its receipt.\",\"evidence\":\"analysis.verify_model_binding BINDING_HONORED\"},{\"obligationId\":\"O6\",\"statement\":\"The checked census is retained and delivered, with each obligation''s fulfilling areas and the check''s reason.\",\"evidence\":\"content-artifact-change COMMITTED; author-workspace-file AUTHORED\"}]}"}';
SELECT N'minted' AS result_set,ordinal,JSON_VALUE(value,'$.artifact_kind') AS artifact_kind,JSON_VALUE(value,'$.action') AS action,JSON_VALUE(value,'$.content_digest') AS content_digest FROM @minted ORDER BY ordinal;
DECLARE @s TABLE(value nvarchar(max)),@c1 TABLE(value nvarchar(max)),@c2 TABLE(value nvarchar(max)),@g1 TABLE(value nvarchar(max)),@g2 TABLE(value nvarchar(max)),@pa TABLE(value nvarchar(max)),@se TABLE(value nvarchar(max)),@bv TABLE(value nvarchar(max)),@bh TABLE(value nvarchar(max));
INSERT @s(value) EXEC analysis.read_capability_census_sources @input=N'{"specDigest":"sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09","projectId":"ov3-complete-agentic-harness","ownerDirectionKind":"owner-direction:ov3-complete-agentic-harness"}';
INSERT @c1(value) EXEC analysis.check_capability_census @input=N'{"censusText":"{\"product\":\"self-test\",\"areas\":[{\"capabilityId\":\"self-test.area\",\"name\":\"Self test\",\"responsibility\":\"Owns the one obligation.\",\"covers\":[\"control-plane\"],\"answers\":[\"owner:1\"],\"existingCapabilities\":[]}]}","obligationsText":"[{\"id\":\"owner:1\",\"text\":\"self-test\"}]","requiredCoverage":"control-plane","specDigest":"sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09","maxAreas":30}';
INSERT @c2(value) EXEC analysis.check_capability_census @input=N'{"censusText":"{\"product\":\"self-test\",\"areas\":[{\"capabilityId\":\"self-test.area\",\"name\":\"Self test\",\"responsibility\":\"Owns one of two obligations.\",\"covers\":[\"control-plane\"],\"answers\":[\"owner:1\"],\"existingCapabilities\":[]}]}","obligationsText":"[{\"id\":\"owner:1\",\"text\":\"self-test\"},{\"id\":\"owner:2\",\"text\":\"unowned\"}]","requiredCoverage":"control-plane","specDigest":"sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09","maxAreas":30}';
INSERT @g1(value) EXEC analysis.check_census_fulfillment @input=N'{"censusText":"{\"product\":\"self-test\",\"specDigest\":\"sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09\",\"obligationCount\":2,\"areas\":[{\"capabilityId\":\"format-labels\",\"name\":\"Format labels\",\"responsibility\":\"Alphabetize display labels\",\"covers\":[\"elaborate-planning\",\"self-improvement\",\"multi-agent-consensus\",\"control-plane\",\"deterministic-multi-step-execution\"],\"answers\":[\"owner:1\",\"owner:2\"],\"existingCapabilities\":[]}]}","obligationsText":"[{\"id\":\"owner:1\",\"text\":\"OV3 plans the work.\"},{\"id\":\"owner:2\",\"text\":\"OV3 corrects the gaps its checks find.\"}]","idStatus":"CENSUS_READY","idFeedback":"No defects.","judgmentText":"{\"verdicts\":[{\"obligationId\":\"owner:1\",\"fulfilledBy\":[],\"reason\":\"Alphabetizing labels plans nothing.\"},{\"obligationId\":\"owner:2\",\"fulfilledBy\":[\"ov3.planning\"],\"reason\":\"Names an area that does not claim it.\"}]}"}';
INSERT @g2(value) EXEC analysis.check_census_fulfillment @input=N'{"censusText":"{\"product\":\"self-test\",\"specDigest\":\"sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09\",\"obligationCount\":2,\"areas\":[{\"capabilityId\":\"ov3.planning\",\"name\":\"Planning and correction\",\"responsibility\":\"Plans the work and corrects the gaps its checks find.\",\"covers\":[\"elaborate-planning\"],\"answers\":[\"owner:1\",\"owner:2\"],\"existingCapabilities\":[]}]}","obligationsText":"[{\"id\":\"owner:1\",\"text\":\"OV3 plans the work.\"},{\"id\":\"owner:2\",\"text\":\"OV3 corrects the gaps its checks find.\"}]","idStatus":"CENSUS_READY","idFeedback":"No defects.","judgmentText":"{\"verdicts\":[{\"obligationId\":\"owner:1\",\"fulfilledBy\":[\"ov3.planning\"],\"reason\":\"It plans the work.\"},{\"obligationId\":\"owner:2\",\"fulfilledBy\":[\"ov3.planning\"],\"reason\":\"It corrects the gaps.\"}]}"}';
INSERT @pa(value) EXEC analysis.apply_census_patch @input=N'{"censusText":"{\"product\":\"self-test\",\"specDigest\":\"sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09\",\"obligationCount\":1,\"areas\":[{\"capabilityId\":\"st.a\",\"name\":\"A\",\"responsibility\":\"A for the self-test.\",\"covers\":[\"control-plane\"],\"answers\":[\"owner:1\"],\"existingCapabilities\":[]},{\"capabilityId\":\"st.b\",\"name\":\"B\",\"responsibility\":\"B for the self-test.\",\"covers\":[\"control-plane\"],\"answers\":[\"owner:1\"],\"existingCapabilities\":[]}]}","patchText":"{\"areas\":[{\"capabilityId\":\"st.b\",\"name\":\"B2\",\"responsibility\":\"B2 for the self-test.\",\"covers\":[\"control-plane\"],\"answers\":[\"owner:1\"],\"existingCapabilities\":[]},{\"capabilityId\":\"st.c\",\"name\":\"C\",\"responsibility\":\"C for the self-test.\",\"covers\":[\"control-plane\"],\"answers\":[\"owner:1\"],\"existingCapabilities\":[]}],\"remove\":[\"st.a\"]}"}';
INSERT @se(value) EXEC analysis.select_census_result @input=N'{"firstStatus":"CENSUS_INVALID","firstCensus":"{\"round\":1}","firstMarkdown":"round 1","firstFeedback":"Defects to fix:","secondStatus":"CENSUS_READY","secondCensus":"{\"round\":2}","secondMarkdown":"round 2","secondFeedback":"No defects."}';
INSERT @bv(value) EXEC analysis.verify_model_binding @input=N'{"calls":[{"step":"self-test","role":"ov3-harness-census-write","provider":"self-test/unselected","model":"none"}]}';
DECLARE @bp nvarchar(400)=(SELECT JSON_VALUE(value,'$.evidence[0].expectedProvider') FROM @bv),@bm nvarchar(400)=(SELECT JSON_VALUE(value,'$.evidence[0].expectedModel') FROM @bv);
DECLARE @bin nvarchar(max)=N'{"calls":'+(SELECT N'self-test' AS step,N'ov3-harness-census-write' AS role,@bp AS provider,@bm AS model FOR JSON PATH)+N'}';
INSERT @bh(value) EXEC analysis.verify_model_binding @input=@bin;
DECLARE @found int=(SELECT TRY_CONVERT(int,JSON_VALUE(value,'$.found')) FROM @s),@obl int=(SELECT TRY_CONVERT(int,JSON_VALUE(value,'$.obligationCount')) FROM @s),@dir int=(SELECT TRY_CONVERT(int,JSON_VALUE(value,'$.directionCount')) FROM @s),
 @proj int=(SELECT TRY_CONVERT(int,JSON_VALUE(value,'$.projectCount')) FROM @s),@task int=(SELECT TRY_CONVERT(int,JSON_VALUE(value,'$.taskCount')) FROM @s);
DECLARE @ready nvarchar(40)=(SELECT JSON_VALUE(value,'$.status') FROM @c1),@gap nvarchar(40)=(SELECT JSON_VALUE(value,'$.status') FROM @c2),@gapIds nvarchar(400)=(SELECT JSON_VALUE(value,'$.unanswered') FROM @c2);
DECLARE @fl nvarchar(40)=(SELECT JSON_VALUE(value,'$.status') FROM @g1),@flFulfilled int=(SELECT TRY_CONVERT(int,JSON_VALUE(value,'$.fulfilledCount')) FROM @g1),@flRejected int=(SELECT TRY_CONVERT(int,JSON_VALUE(value,'$.rejectedClaims')) FROM @g1),
 @pass nvarchar(40)=(SELECT JSON_VALUE(value,'$.status') FROM @g2),@passFulfilled int=(SELECT TRY_CONVERT(int,JSON_VALUE(value,'$.fulfilledCount')) FROM @g2);
DECLARE @patched nvarchar(400)=(SELECT CONCAT(JSON_VALUE(value,'$.removed'),N'/',JSON_VALUE(value,'$.replaced'),N'/',JSON_VALUE(value,'$.added'),N' ',JSON_VALUE(JSON_VALUE(value,'$.census'),'$.areas[0].name'),N',',JSON_VALUE(JSON_VALUE(value,'$.census'),'$.areas[1].capabilityId')) FROM @pa);
DECLARE @sel nvarchar(400)=(SELECT CONCAT(JSON_VALUE(value,'$.status'),N' ',JSON_VALUE(value,'$.round'),N' ',JSON_VALUE(value,'$.censusJson')) FROM @se),
 @bvs nvarchar(40)=(SELECT JSON_VALUE(value,'$.status') FROM @bv),@bhs nvarchar(40)=(SELECT JSON_VALUE(value,'$.status') FROM @bh);
SELECT N'self_test' AS result_set,@found AS spec_found,@obl AS obligations,@proj AS projects,@task AS tasks,@dir AS owner_lines,@ready AS owned_census,@gap AS gap_census,@gapIds AS gap_named,
 @fl AS format_labels_gate,@flFulfilled AS format_labels_fulfilled,@flRejected AS format_labels_rejected,@pass AS fulfilled_gate,@passFulfilled AS fulfilled_count,@patched AS patch_applied,
 @sel AS round_selected,@bp AS bound_provider,@bm AS bound_model,@bvs AS unselected_receipt,@bhs AS selected_receipt;
IF ISNULL(@found,0)<>1 OR ISNULL(@dir,0)<>17 OR ISNULL(@proj,0)<1 OR ISNULL(@task,0)<1 OR ISNULL(@obl,0)<>ISNULL(@proj,0)+ISNULL(@task,0)+ISNULL(@dir,0) OR ISNULL(@ready,N'')<>N'CENSUS_READY'
 OR ISNULL(@gap,N'')<>N'CENSUS_INVALID' OR ISNULL(@gapIds,N'')<>N'owner:2' OR ISNULL(@fl,N'')<>N'CENSUS_INVALID' OR ISNULL(@flFulfilled,-1)<>0 OR ISNULL(@flRejected,-1)<>2
 OR ISNULL(@pass,N'')<>N'CENSUS_READY' OR ISNULL(@passFulfilled,-1)<>2 OR ISNULL(@patched,N'')<>N'1/1/1 B2,st.c'
 OR ISNULL(@sel,N'')<>N'CENSUS_READY 2 {"round":2}' OR @bp IS NULL OR ISNULL(@bvs,N'')<>N'BINDING_VIOLATED' OR ISNULL(@bhs,N'')<>N'BINDING_HONORED'
BEGIN
 RAISERROR(N'OV3_HARNESS_SELF_TEST_FAILED: the census procedures did not answer as probed; nothing is kept.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
SELECT N'readback' AS result_set,e.artifact_kind,e.expected_digest,N'sha256:'+LOWER(CONVERT(varchar(64),x.content_digest,2)) AS newest_digest,CASE WHEN x.content_digest=CONVERT(binary(32),e.expected_hex,1) THEN 1 ELSE 0 END AS matches
FROM (VALUES
 (N'owner-direction:ov3-complete-agentic-harness','sha256:f700c5c7008564789b3d8b60afb3d1511da7d0f0d4e350a8f76977a97eeaad7b','0xf700c5c7008564789b3d8b60afb3d1511da7d0f0d4e350a8f76977a97eeaad7b'),
 (N'flight-clearance-policy:owner-objective','sha256:07f9005b27fa539c4d39e28ed9ab2ca4df50e1455aaa54ba1db8ef33a578bc0a','0x07f9005b27fa539c4d39e28ed9ab2ca4df50e1455aaa54ba1db8ef33a578bc0a'),
 (N'flight-promise:ov3-harness-census-2','sha256:500f3152c7f739056b409773a097e749c0407000dcf59457ba8c927773589ed7','0x500f3152c7f739056b409773a097e749c0407000dcf59457ba8c927773589ed7')
) e(artifact_kind,expected_digest,expected_hex)
OUTER APPLY (SELECT TOP (1) a.content_digest FROM model.content_artifact a WHERE a.artifact_kind=e.artifact_kind COLLATE Latin1_General_100_BIN2 ORDER BY a.registered_date DESC,a.content_artifact_pk DESC) x;
ROLLBACK TRANSACTION;
GO
SET NOEXEC OFF;
